CREATE TABLE rule_steward_mechanic(rule_id bigint PRIMARY KEY REFERENCES rule_rule(rule_id),skill_rule_id bigint NOT NULL UNIQUE REFERENCES rule_skill(rule_id),serves_nobles boolean NOT NULL CHECK(serves_nobles),serves_high_passengers boolean NOT NULL CHECK(serves_high_passengers));
CREATE TABLE rule_steward_service(rule_id bigint NOT NULL REFERENCES rule_steward_mechanic(rule_id),service_code text NOT NULL CHECK(service_code IN('concierge','housekeeping','meal-preparation-presentation','personal-grooming-assistance','valet','social-etiquette')),display_order smallint NOT NULL CHECK(display_order>0),PRIMARY KEY(rule_id,service_code),UNIQUE(rule_id,display_order));
COMMENT ON TABLE rule_steward_service IS 'CE-SKILL-015 paired-source Steward duties for nobles and high-class passengers.';
